insert into public.problem_definitions(problem_id,version,data) values ('contains-duplicate',1,'{"id":"contains-duplicate","version":1,"functionName":"containsDuplicate","prompt":"Given a list of integers, return true if any value appears more than once. Return false if every value is distinct. The input may be empty.","constraints":["0 ≤ number of elements ≤ 100,000","Elements are integers between −1,000,000,000 and 1,000,000,000"],"parameters":[{"name":"nums","py":"List[int]","ts":"number[]"}],"returnType":{"py":"bool","ts":"boolean"},"tests":[{"name":"Repeated value","args":[[4,2,4]],"expected":true,"example":true},{"name":"Distinct values","args":[[3,7,9]],"expected":false,"example":true},{"name":"Empty list","args":[[]],"expected":false},{"name":"Single value","args":[[5]],"expected":false},{"name":"Negative duplicate","args":[[-2,0,-2]],"expected":true},{"name":"Repeated zero","args":[[0,0]],"expected":true}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('valid-anagram',1,'{"id":"valid-anagram","version":1,"functionName":"isAnagram","prompt":"Return whether two lowercase English strings contain exactly the same characters with the same frequencies. Character order does not matter; empty strings are allowed.","constraints":["0 ≤ string length ≤ 50,000","Only lowercase English letters"],"parameters":[{"name":"s","py":"str","ts":"string"},{"name":"t","py":"str","ts":"string"}],"returnType":{"py":"bool","ts":"boolean"},"tests":[{"name":"Same letters","args":["listen","silent"],"expected":true,"example":true},{"name":"Different frequencies","args":["aab","abb"],"expected":false,"example":true},{"name":"Empty strings","args":["",""],"expected":true},{"name":"Different lengths","args":["a","aa"],"expected":false},{"name":"Repeated letters","args":["aaaa","aaaa"],"expected":true},{"name":"Different characters","args":["ab","cd"],"expected":false}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('two-sum',1,'{"id":"two-sum","version":1,"functionName":"twoSum","comparison":"two-sum","prompt":"Find two different indices whose values add up to target. Exactly one pair exists. Return the indices in either order, and do not use an element twice.","constraints":["2 ≤ number of elements ≤ 10,000","Exactly one valid pair exists"],"parameters":[{"name":"nums","py":"List[int]","ts":"number[]"},{"name":"target","py":"int","ts":"number"}],"returnType":{"py":"List[int]","ts":"number[]"},"tests":[{"name":"First and last","args":[[8,2,6,5],13],"expected":[0,3],"example":true},{"name":"Same value, different indices","args":[[4,4],8],"expected":[0,1],"example":true},{"name":"Negative values","args":[[-5,1,7,-2],-7],"expected":[0,3]},{"name":"Zero pair","args":[[0,9,0],0],"expected":[0,2]},{"name":"Middle pair","args":[[9,3,6,12],9],"expected":[1,2]}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('group-anagrams',1,'{"id":"group-anagrams","version":1,"functionName":"groupAnagrams","comparison":"unordered-groups","prompt":"Group a list of lowercase English words so that each group contains words made of the same letters with the same frequencies. Both the order of groups and the order within a group may vary. Preserve repeated words.","constraints":["0 ≤ number of words ≤ 10,000","A word can be empty"],"parameters":[{"name":"strs","py":"List[str]","ts":"string[]"}],"returnType":{"py":"List[List[str]]","ts":"string[][]"},"tests":[{"name":"Multiple groups","args":[["eat","tea","now","won","ate"]],"expected":[["eat","tea","ate"],["now","won"]],"example":true},{"name":"Empty word","args":[[""]],"expected":[[""]],"example":true},{"name":"Empty list","args":[[]],"expected":[]},{"name":"Repeated words","args":[["ab","ba","ab"]],"expected":[["ab","ba","ab"]]},{"name":"Different frequencies","args":[["aa","a",""]],"expected":[["aa"],["a"],[""]]}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('valid-palindrome',1,'{"id":"valid-palindrome","version":1,"functionName":"isPalindrome","prompt":"Ignore characters other than ASCII letters and digits, and compare letters without case. Return whether the remaining sequence reads the same forwards and backwards. An empty remaining sequence is a palindrome.","constraints":["0 ≤ string length ≤ 200,000","Input contains ASCII characters"],"parameters":[{"name":"s","py":"str","ts":"string"}],"returnType":{"py":"bool","ts":"boolean"},"tests":[{"name":"Punctuation and case","args":["Was it a car or a cat I saw?"],"expected":true,"example":true},{"name":"Not symmetric","args":["software"],"expected":false,"example":true},{"name":"Empty string","args":[""],"expected":true},{"name":"Only punctuation","args":["!?  ."],"expected":true},{"name":"Digits matter","args":["0P"],"expected":false},{"name":"Mixed palindrome","args":["1aA1"],"expected":true}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('3sum',1,'{"id":"3sum","version":1,"functionName":"threeSum","comparison":"unordered-groups","prompt":"Return all distinct triplets of values that sum to zero. Each triplet must use three different positions in the input. The order of triplets and values within each triplet is unrestricted, but duplicate triplets are not allowed.","constraints":["0 ≤ number of elements ≤ 3,000","Elements are integers between −100,000 and 100,000"],"parameters":[{"name":"nums","py":"List[int]","ts":"number[]"}],"returnType":{"py":"List[List[int]]","ts":"number[][]"},"tests":[{"name":"Two distinct triplets","args":[[-2,0,1,1,2]],"expected":[[-2,0,2],[-2,1,1]],"example":true},{"name":"All zeros","args":[[0,0,0,0]],"expected":[[0,0,0]],"example":true},{"name":"Empty list","args":[[]],"expected":[]},{"name":"Too few values","args":[[0,0]],"expected":[]},{"name":"No triplets","args":[[1,2,3]],"expected":[]},{"name":"Duplicates","args":[[-1,-1,0,1,1,2]],"expected":[[-1,-1,2],[-1,0,1]]}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('best-time-to-buy-and-sell-stock',1,'{"id":"best-time-to-buy-and-sell-stock","version":1,"functionName":"maxProfit","prompt":"A list gives the stock price on each day. Choose at most one buy and one later sell to maximize profit. Return zero if no profitable trade exists.","constraints":["0 ≤ number of prices ≤ 100,000","Prices are nonnegative integers"],"parameters":[{"name":"prices","py":"List[int]","ts":"number[]"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Buy before selling","args":[[8,3,6,2,9]],"expected":7,"example":true},{"name":"Prices decline","args":[[9,7,4,1]],"expected":0,"example":true},{"name":"Empty list","args":[[]],"expected":0},{"name":"One day","args":[[4]],"expected":0},{"name":"Increasing prices","args":[[1,2,3,4]],"expected":3},{"name":"Same price","args":[[2,2,2]],"expected":0}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('longest-substring-without-repeating-characters',1,'{"id":"longest-substring-without-repeating-characters","version":1,"functionName":"lengthOfLongestSubstring","prompt":"Return the length of the longest contiguous substring with no repeated character. Spaces and punctuation count as characters.","constraints":["0 ≤ string length ≤ 50,000","Input contains ASCII characters"],"parameters":[{"name":"s","py":"str","ts":"string"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Repeated pattern","args":["abcabc"],"expected":3,"example":true},{"name":"All repeated","args":["zzzz"],"expected":1,"example":true},{"name":"Empty string","args":[""],"expected":0},{"name":"Overlapping repetition","args":["abba"],"expected":2},{"name":"Space is a character","args":["a b!a"],"expected":4},{"name":"Distinct string","args":["coding"],"expected":6}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('valid-parentheses',1,'{"id":"valid-parentheses","version":1,"functionName":"isValid","prompt":"A string contains only parentheses, square brackets, and braces. Return whether every opening bracket is closed by a matching bracket in the correct nested order. The empty string is valid.","constraints":["0 ≤ string length ≤ 10,000","Characters are from ()[]{}"],"parameters":[{"name":"s","py":"str","ts":"string"}],"returnType":{"py":"bool","ts":"boolean"},"tests":[{"name":"Nested brackets","args":["{[()]}"],"expected":true,"example":true},{"name":"Crossed brackets","args":["([)]"],"expected":false,"example":true},{"name":"Empty string","args":[""],"expected":true},{"name":"Unclosed","args":["(("],"expected":false},{"name":"Unexpected closing","args":[")("],"expected":false},{"name":"Adjacent pairs","args":["()[]{}"],"expected":true}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('binary-search',1,'{"id":"binary-search","version":1,"functionName":"search","prompt":"Given integers sorted in strictly increasing order, return the index of target or −1 if it is missing. Aim for logarithmic time.","constraints":["0 ≤ number of elements ≤ 10,000","All elements are distinct and sorted"],"parameters":[{"name":"nums","py":"List[int]","ts":"number[]"},{"name":"target","py":"int","ts":"number"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Found in the middle","args":[[-3,0,4,8,12],8],"expected":3,"example":true},{"name":"Missing target","args":[[1,3,5],4],"expected":-1,"example":true},{"name":"Empty list","args":[[],1],"expected":-1},{"name":"First element","args":[[2,4,6],2],"expected":0},{"name":"Last element","args":[[2,4,6],6],"expected":2},{"name":"Single element","args":[[9],9],"expected":0}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('reverse-linked-list',1,'{"id":"reverse-linked-list","version":1,"functionName":"reverseList","inputKind":"linked-list","prompt":"Reverse a singly linked list and return its new head. The harness supplies ListNode with val and next fields. Examples and custom inputs represent linked lists as arrays of values; an empty array represents a null head.","constraints":["0 ≤ number of nodes ≤ 5,000","Return a ListNode or null, not an array"],"parameters":[{"name":"head","py":"Optional[ListNode]","ts":"ListNode | null"}],"returnType":{"py":"Optional[ListNode]","ts":"ListNode | null"},"tests":[{"name":"Several nodes","args":[[3,5,8]],"expected":[8,5,3],"example":true},{"name":"Single node","args":[[7]],"expected":[7],"example":true},{"name":"Empty list","args":[[]],"expected":[]},{"name":"Two nodes","args":[[1,2]],"expected":[2,1]},{"name":"Repeated values","args":[[2,2,1]],"expected":[1,2,2]}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('maximum-depth-of-binary-tree',1,'{"id":"maximum-depth-of-binary-tree","version":1,"functionName":"maxDepth","inputKind":"binary-tree","prompt":"Return the number of nodes along the longest root-to-leaf path in a binary tree. The harness supplies TreeNode with val, left, and right fields. Inputs use level-order arrays where null marks a missing child. An empty array represents an empty tree.","constraints":["0 ≤ number of nodes ≤ 10,000","The depth of an empty tree is zero"],"parameters":[{"name":"root","py":"Optional[TreeNode]","ts":"TreeNode | null"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Balanced tree","args":[[4,2,7,1,3]],"expected":3,"example":true},{"name":"Empty tree","args":[[]],"expected":0,"example":true},{"name":"One node","args":[[8]],"expected":1},{"name":"Right branch","args":[[1,null,2,null,3]],"expected":3},{"name":"Sparse branches","args":[[1,2,3,null,4,null,5,6]],"expected":4}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('subsets',1,'{"id":"subsets","version":1,"functionName":"subsets","comparison":"unordered-groups","prompt":"Return every subset of a list of distinct integers, including the empty subset and the full list. Each subset must occur exactly once. Subset order and the order of elements within a subset do not matter.","constraints":["0 ≤ number of elements ≤ 10","All input elements are distinct"],"parameters":[{"name":"nums","py":"List[int]","ts":"number[]"}],"returnType":{"py":"List[List[int]]","ts":"number[][]"},"tests":[{"name":"Two elements","args":[[2,5]],"expected":[[],[2],[5],[2,5]],"example":true},{"name":"Empty list","args":[[]],"expected":[[]],"example":true},{"name":"One element","args":[[0]],"expected":[[],[0]]},{"name":"Negative element","args":[[-1,3]],"expected":[[],[-1],[3],[-1,3]]},{"name":"Three elements","args":[[1,2,3]],"expected":[[],[1],[2],[3],[1,2],[1,3],[2,3],[1,2,3]]}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('number-of-islands',1,'{"id":"number-of-islands","version":1,"functionName":"numIslands","prompt":"A rectangular grid contains strings ''1'' for land and ''0'' for water. Count connected groups of land. Cells connect horizontally and vertically, but not diagonally. An empty grid contains zero islands.","constraints":["0 ≤ rows, columns ≤ 300","All rows have equal length"],"parameters":[{"name":"grid","py":"List[List[str]]","ts":"string[][]"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Separate groups","args":[[["1","1","0"],["0","0","1"],["1","0","1"]]],"expected":3,"example":true},{"name":"All water","args":[[["0","0"],["0","0"]]],"expected":0,"example":true},{"name":"Empty grid","args":[[]],"expected":0},{"name":"Diagonal land","args":[[["1","0"],["0","1"]]],"expected":2},{"name":"All connected","args":[[["1","1"],["1","1"]]],"expected":1},{"name":"Single row","args":[[["1","0","1","1","0"]]],"expected":2}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
insert into public.problem_definitions(problem_id,version,data) values ('climbing-stairs',1,'{"id":"climbing-stairs","version":1,"functionName":"climbStairs","prompt":"You can climb either one or two stairs per move. Return the number of different sequences of moves that reach exactly n stairs. For zero stairs, there is one sequence: take no moves.","constraints":["0 ≤ n ≤ 45","Different move orders count separately"],"parameters":[{"name":"n","py":"int","ts":"number"}],"returnType":{"py":"int","ts":"number"},"tests":[{"name":"Three stairs","args":[3],"expected":3,"example":true},{"name":"Four stairs","args":[4],"expected":5,"example":true},{"name":"Zero stairs","args":[0],"expected":1},{"name":"One stair","args":[1],"expected":1},{"name":"Two stairs","args":[2],"expected":2},{"name":"Larger input","args":[20],"expected":10946},{"name":"Upper bound","args":[45],"expected":1836311903}]}'::jsonb) on conflict (problem_id,version) do update set data=excluded.data;
